public class Main {
    enum State { CLOSED, OPEN, HALF_OPEN }

    static class CircuitBreaker {
        private State state = State.CLOSED;
        private int consecutiveFailures = 0;
        private final int failureThreshold;
        private int callsSinceOpened = 0;
        private final int cooldownCalls;

        CircuitBreaker(int failureThreshold, int cooldownCalls) {
            this.failureThreshold = failureThreshold;
            this.cooldownCalls = cooldownCalls;
        }

        String call(boolean dependencyWillSucceed) {
            if (state == State.OPEN) {
                callsSinceOpened++;
                if (callsSinceOpened < cooldownCalls) {
                    return "REJECTED: circuit open, call not attempted";
                }
                state = State.HALF_OPEN;
            }

            if (state == State.HALF_OPEN) {
                if (dependencyWillSucceed) {
                    state = State.CLOSED;
                    consecutiveFailures = 0;
                    return "SUCCESS: probe passed, circuit closed again";
                } else {
                    state = State.OPEN;
                    callsSinceOpened = 0;
                    return "FAILED: probe failed, circuit stays open";
                }
            }

            // state == CLOSED
            if (dependencyWillSucceed) {
                consecutiveFailures = 0;
                return "SUCCESS: call completed normally";
            } else {
                consecutiveFailures++;
                if (consecutiveFailures >= failureThreshold) {
                    state = State.OPEN;
                    callsSinceOpened = 0;
                    return "FAILED: threshold reached, circuit now open";
                }
                return "FAILED: call failed, circuit still closed";
            }
        }
    }

    public static void main(String[] args) {
        CircuitBreaker breaker = new CircuitBreaker(3, 5);
        boolean[] outcomes = {true, false, false, false, false, false, false, true, true};

        for (boolean outcome : outcomes) {
            System.out.println(breaker.call(outcome));
        }
    }
}

