class State:
    CLOSED = "CLOSED"
    OPEN = "OPEN"
    HALF_OPEN = "HALF_OPEN"


class CircuitBreaker:
    def __init__(self, failure_threshold, cooldown_calls):
        self.state = State.CLOSED
        self.consecutive_failures = 0
        self.failure_threshold = failure_threshold
        self.calls_since_opened = 0
        self.cooldown_calls = cooldown_calls

    def call(self, dependency_will_succeed):
        if self.state == State.OPEN:
            self.calls_since_opened += 1
            if self.calls_since_opened < self.cooldown_calls:
                return "REJECTED: circuit open, call not attempted"
            self.state = State.HALF_OPEN

        if self.state == State.HALF_OPEN:
            if dependency_will_succeed:
                self.state = State.CLOSED
                self.consecutive_failures = 0
                return "SUCCESS: probe passed, circuit closed again"
            else:
                self.state = State.OPEN
                self.calls_since_opened = 0
                return "FAILED: probe failed, circuit stays open"

        # state == CLOSED
        if dependency_will_succeed:
            self.consecutive_failures = 0
            return "SUCCESS: call completed normally"
        else:
            self.consecutive_failures += 1
            if self.consecutive_failures >= self.failure_threshold:
                self.state = State.OPEN
                self.calls_since_opened = 0
                return "FAILED: threshold reached, circuit now open"
            return "FAILED: call failed, circuit still closed"


def main():
    breaker = CircuitBreaker(3, 5)
    outcomes = [True, False, False, False, False, False, False, True, True]

    for outcome in outcomes:
        print(breaker.call(outcome))


if __name__ == "__main__":
    main()

