#include <iostream>
#include <vector>
using namespace std;

enum class State { CLOSED, OPEN, HALF_OPEN };

class CircuitBreaker {
public:
    CircuitBreaker(int failureThreshold, int cooldownCalls)
        : state(State::CLOSED), consecutiveFailures(0),
          failureThreshold(failureThreshold), callsSinceOpened(0),
          cooldownCalls(cooldownCalls) {}

    string call(bool dependencyWillSucceed) {
        if (state == State::OPEN) {
            callsSinceOpened++;
            if (callsSinceOpened < cooldownCalls) {
                return "REJECTED: circuit open, call not attempted";
            }
            state = State::HALF_OPEN;
        }

        if (state == State::HALF_OPEN) {
            if (dependencyWillSucceed) {
                state = State::CLOSED;
                consecutiveFailures = 0;
                return "SUCCESS: probe passed, circuit closed again";
            } else {
                state = State::OPEN;
                callsSinceOpened = 0;
                return "FAILED: probe failed, circuit stays open";
            }
        }

        // state == CLOSED
        if (dependencyWillSucceed) {
            consecutiveFailures = 0;
            return "SUCCESS: call completed normally";
        } else {
            consecutiveFailures++;
            if (consecutiveFailures >= failureThreshold) {
                state = State::OPEN;
                callsSinceOpened = 0;
                return "FAILED: threshold reached, circuit now open";
            }
            return "FAILED: call failed, circuit still closed";
        }
    }

private:
    State state;
    int consecutiveFailures;
    int failureThreshold;
    int callsSinceOpened;
    int cooldownCalls;
};

int main() {
    CircuitBreaker breaker(3, 5);
    vector<bool> outcomes = {true, false, false, false, false, false, false, true, true};

    for (bool outcome : outcomes) {
        cout << breaker.call(outcome) << endl;
    }

    return 0;
}
